H,W=14,17
G=[[0]*W for _ in range(H)]
markers=[(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)]
for r,c in markers:G[r][c]=2
# Connect the horizontally aligned pair as a 3-span, and connect each other marker vertically to that row.
axis=8
for c in range(1,13):
    if G[axis][c]==0:G[axis][c]=3
for r,c in markers:
    if r<axis:
        for rr in range(r+1,axis):
            if G[rr][c]==0:G[rr][c]=3
    elif r>axis:
        for rr in range(axis+1,r):
            if G[rr][c]==0:G[rr][c]=3
assert len(G)==14 and all(len(row)==17 for row in G)
assert set(sum(G,[])) <= {0,2,3}
print('\n'.join(' '.join(map(str,row)) for row in G))
